use std::collections::HashSet;

// The function removes duplicates from the input vector `nums`.
// It returns a new vector with the same elements but without any duplicates.
// The order of elements in the output preserves the first occurrence in the input.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for &num in &nums {
        if seen.insert(num) {
            // If insert returns true, this is the first time seeing `num`.
            result.push(num);
        }
    }
    result
}

